function Invoke-WorkflowOpenSession {
    # TR-MCP-REPL-011: persist an explicit valid sessionId into session-state.yaml instead of the
    # historical no-op, so an explicit openSession can recover a bad/rotated local session id
    # (BUG-TRIAGE-085; previously documented as a gap in GAPS.md).
    param(
        [string]$ParamsYaml,
        [string]$CacheDir = '',
        [string]$SessionId = '',
        [string]$RootSessionId = ''
    )
    if (-not [string]::IsNullOrWhiteSpace($CacheDir) -and -not [string]::IsNullOrWhiteSpace($SessionId)) {
        Write-ReplStickySessionState -CacheDir $CacheDir -RootSessionId $RootSessionId -SessionId $SessionId | Out-Null
        return $true
    }

    $params = Convert-ReplParamsYamlToObject -ParamsYaml $ParamsYaml
    $sessionId = ''
    if ($params -is [System.Collections.IDictionary] -and $params.Contains('sessionId')) {
        $sessionId = [string]$params['sessionId']
    } elseif ($params -and $params.PSObject.Properties['sessionId']) {
        $sessionId = [string]$params.PSObject.Properties['sessionId'].Value
    }
    if ([string]::IsNullOrWhiteSpace($sessionId)) { return $false }

    $sessionId = ConvertTo-ReplCanonicalSessionId -SessionId $sessionId.Trim()
    $cacheDir = Get-ReplInvokeCacheDir
    $rootSessionFile = Join-Path $cacheDir 'session-state.yaml'
    $rootState = if (Test-Path -LiteralPath $rootSessionFile) { Read-McpYamlObject -Path $rootSessionFile } else { $null }
    $rootSessionId = ''
    if ($rootState -is [System.Collections.IDictionary] -and $rootState.Contains('sessionId')) {
        $rootSessionId = [string]$rootState['sessionId']
    }
    $isChild = $false
    if ($params -is [System.Collections.IDictionary]) {
        $isChild = [bool]($params['background'] -or $params['child'] -or $params['sessionKey'])
    }
    if (-not $isChild -and -not [string]::IsNullOrWhiteSpace($rootSessionId) -and $rootSessionId -ne $sessionId) {
        $isChild = $true
    }
    $sessionFile = Write-ReplStickySessionState -CacheDir $cacheDir -RootSessionId $rootSessionId -SessionId $sessionId -Child:$isChild
    $state = Read-McpYamlObject -Path $sessionFile -Create
    if ($state -isnot [System.Collections.IDictionary]) { $state = [ordered]@{} }
    $state['status'] = 'verified'
    $state['sessionId'] = $sessionId
    if (-not $state.Contains('agent') -or [string]::IsNullOrWhiteSpace([string]$state['agent'])) {
        $state['agent'] = Get-ReplCanonicalAgentName $script:AgentName
    }
    $state['lastUpdated'] = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
    Write-McpYamlObject -Path $sessionFile -Document $state
    return $true
}


function Resolve-ReplWorkspaceDirectory {
    # A marker-bearing current directory outranks the workspace env vars: ambient
    # MCP_WORKSPACE_PATH values leak across workspaces through host processes and
    # persistent consoles, and an inherited value must not re-bind marker trust,
    # API keys, and session logs to another workspace while the cache directory
    # stays local (triage-report-7c84e6437f7b42d0a67fbe32679a686a). This matches
    # the plugin hook's Get-PluginStartPath precedence.
    $providerLocation = $null
    try {
        $location = Get-Location
        if ($location.Provider.Name -eq 'FileSystem') {
            $providerLocation = $location.ProviderPath
        }
    } catch {
        # Fall through to the env and .NET current directory fallbacks.
    }

    # Only the PowerShell provider location is trusted for the marker check: the
    # process-wide [Environment]::CurrentDirectory can be stale in shared hosts.
    if (-not [string]::IsNullOrWhiteSpace($providerLocation) -and
        (Test-Path -LiteralPath $providerLocation -PathType Container)) {
        try {
            if ((Get-Command Find-MarkerFile -ErrorAction SilentlyContinue) -and
                (Find-MarkerFile -StartDir $providerLocation)) {
                return (Resolve-Path -LiteralPath $providerLocation).ProviderPath
            }
        } catch {
            # No marker above the current directory; consult the env fallbacks below.
        }
    }

    $candidates = @(
        $env:MCP_WORKSPACE_PATH,
        $env:MCPSERVER_WORKSPACE_PATH,
        $env:MCP_WORKSPACE_START_DIR,
        $env:CLAUDE_PROJECT_DIR,
        $providerLocation,
        [Environment]::CurrentDirectory
    )

    foreach ($candidate in $candidates) {
        if ([string]::IsNullOrWhiteSpace($candidate)) { continue }
        if (Test-Path -LiteralPath $candidate -PathType Container) {
            return (Resolve-Path -LiteralPath $candidate).ProviderPath
        }
    }

    return (Get-Location).ProviderPath
}

function Assert-ReplMarkerFresh {
    $workspace = Resolve-ReplWorkspaceDirectory
    $sessionFile = Join-Path (Get-ReplInvokeCacheDir) 'session-state.yaml'

    try {
        $snapshot = Get-MarkerFileSnapshot -StartDir $workspace
        $state = Read-McpYamlObject -Path $sessionFile -Create
        if ($state -isnot [System.Collections.IDictionary]) {
            $state = [ordered]@{}
        }

        $status = if ($state.Contains('status')) { [string]$state['status'] } else { '' }
        $cachedPath = if ($state.Contains('markerFilePath')) { [string]$state['markerFilePath'] } else { '' }
        $cachedWriteUtc = if ($state.Contains('markerLastWriteUtc')) { [string]$state['markerLastWriteUtc'] } else { '' }
        $cachedSessionId = if ($state.Contains('sessionId')) { [string]$state['sessionId'] } else { '' }

        if ($status -eq 'verified' -and
            $cachedPath -eq $snapshot.markerFilePath -and
            $cachedWriteUtc -eq $snapshot.markerLastWriteUtc -and
            -not [string]::IsNullOrWhiteSpace($cachedSessionId)) {
            return $true
        }

        if (-not (Invoke-FullBootstrap -StartDir $workspace)) {
            throw 'marker bootstrap failed'
        }
        $snapshot = Get-MarkerFileSnapshot -StartDir $workspace

        $state['status'] = 'verified'
        if (-not $state.Contains('agent')) {
            $state['agent'] = $script:AgentName
        }
        if (-not $state.Contains('sessionId') -or [string]::IsNullOrWhiteSpace([string]$state['sessionId'])) {
            $state['sessionId'] = New-ReplPluginSessionId
        }
        $state['lastUpdated'] = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
        $state['markerFilePath'] = $snapshot.markerFilePath
        $state['markerLastWriteUtc'] = $snapshot.markerLastWriteUtc
        Write-McpYamlObject -Path $sessionFile -Document $state
        return $true
    } catch {
        $untrustedState = [ordered]@{
            status = 'MCP_UNTRUSTED'
            lastUpdated = (Get-Date).ToUniversalTime().ToString('yyyy-MM-ddTHH:mm:ssZ')
        }
        try {
            $snapshot = Get-MarkerFileSnapshot -StartDir $workspace
            $untrustedState['markerFilePath'] = $snapshot.markerFilePath
            $untrustedState['markerLastWriteUtc'] = $snapshot.markerLastWriteUtc
        } catch {
        }
        Write-McpYamlObject -Path $sessionFile -Document $untrustedState
        [Console]::Error.WriteLine("MCP_UNTRUSTED: marker refresh failed before REPL request: $_")
        return $false
    }
}

function Set-ReplProcessWorkspace {
    param([Parameter(Mandatory)][System.Diagnostics.ProcessStartInfo]$StartInfo)

    $workspace = Resolve-ReplWorkspaceDirectory
    $StartInfo.WorkingDirectory = $workspace
    $StartInfo.Environment['MCP_WORKSPACE_PATH'] = $workspace
    $StartInfo.Environment['MCPSERVER_WORKSPACE_PATH'] = $workspace
    $StartInfo.Environment['MCP_WORKSPACE_START_DIR'] = $workspace
    $StartInfo.Environment['CLAUDE_PROJECT_DIR'] = $workspace
}

function Convert-ReplParamsYamlToObject {
    param([string]$ParamsYaml)

    if (-not $ParamsYaml) { return $null }

    $normalized = $ParamsYaml -replace "`r`n", "`n" -replace "`r", ""
    if ($normalized.TrimStart() -match '^[\{\[]') {
        return ($normalized | ConvertFrom-Json -Depth 100 -ErrorAction Stop)
    }

namespace QBrainAi.Support.Mcp.Services;

/// <summary>
/// TR-MCP-WS-005 / AC-TR-MCP-WS-005-001, TR-MCP-SESSIONLOG-006 / AC-TR-MCP-SESSIONLOG-006-009:
/// walks a directory tree under the user profile breadth first without following directory links or other
/// reparse points, and skips the contents of any directory whose listing fails with an IO or access error
/// (an untrusted mount point, an access-denied or vanished folder), so a scan never fails on what it cannot
/// traverse.
/// </summary>
/// <remarks>
/// A directory is yielded when its parent lists it, unless it is a link; its contents are walked only when its own
/// listing succeeds. File links are yielded as files. Listing errors other than <see cref="IOException"/> and
/// <see cref="UnauthorizedAccessException"/> propagate. A scan root below the user profile or home is walked only
/// when <see cref="IsReachable"/> holds for it (hostile validation round 5 finding R5-F1; operator 2026-10-21:
/// "Fix both, strengthen ACs").
/// </remarks>
internal sealed class DirectoryTreeWalker
{
    private static readonly StringComparison s_pathComparison =
        OperatingSystem.IsWindows() ? StringComparison.OrdinalIgnoreCase : StringComparison.Ordinal;

    private static readonly EnumerationOptions s_singleLevel = new()
    {
        RecurseSubdirectories = false,
        IgnoreInaccessible = false,
        AttributesToSkip = 0,
        ReturnSpecialDirectories = false,
    };

    private readonly Func<string, IReadOnlyList<DirectoryListingEntry>> _list;

    /// <summary>Creates a walker that lists each directory through <paramref name="list"/>.</summary>
    /// <param name="list">Lists one directory, or throws when it cannot be listed.</param>
    internal DirectoryTreeWalker(Func<string, IReadOnlyList<DirectoryListingEntry>> list)
    {
        ArgumentNullException.ThrowIfNull(list);
        _list = list;
    }

    /// <summary>The walker over the real file system.</summary>
    internal static DirectoryTreeWalker FileSystem { get; } = new(ListFileSystem);

    /// <summary>Every directory below <paramref name="root"/> that the walk reaches.</summary>
    /// <param name="root">Directory to walk; it is listed but not yielded.</param>
    /// <returns>The reached directories, breadth first.</returns>
    internal IEnumerable<string> EnumerateDirectories(string root) => Walk(root, yieldDirectories: true);

    /// <summary>Every file below <paramref name="root"/> that the walk reaches.</summary>
    /// <param name="root">Directory to walk.</param>
    /// <returns>The reached files, breadth first.</returns>
    internal IEnumerable<string> EnumerateFiles(string root) => Walk(root, yieldDirectories: false);

    /// <summary>
    /// AC-TR-MCP-WS-005-001, AC-TR-MCP-SESSIONLOG-006-009: whether <paramref name="root"/> may be walked from
    /// <paramref name="boundary"/>: the root and every folder between the boundary and it must each be listed by
    /// its parent as a directory that is not a link or other reparse point. The boundary itself is trusted (a user
    /// profile or home that is itself a link is still scanned) and its parent is never listed; a root that is the
    /// boundary is reachable without any listing.
    /// </summary>
    /// <remarks>
    /// A folder whose listing fails with an <see cref="IOException"/> or <see cref="UnauthorizedAccessException"/>
    /// cannot be traversed, so the root is not reachable; any other listing error propagates. A root that is not
    /// below the boundary, or that a parent does not list as a directory, is not reachable.
    /// </remarks>
    /// <param name="boundary">The trusted folder the scan starts from (the user profile or home).</param>
    /// <param name="root">The scan root below <paramref name="boundary"/>.</param>
    /// <returns>True when the root may be walked.</returns>
    internal bool IsReachable(string boundary, string root)
    {
        ArgumentNullException.ThrowIfNull(boundary);
        ArgumentNullException.ThrowIfNull(root);
        var target = Path.TrimEndingDirectorySeparator(root);
        var current = Path.TrimEndingDirectorySeparator(boundary);
        while (!string.Equals(current, target, s_pathComparison))
        {
            IReadOnlyList<DirectoryListingEntry> entries;
            try
            {
                entries = _list(current);
            }
            catch (IOException)
            {
                return false;
            }
            catch (UnauthorizedAccessException)
            {
                return false;
            }

            var found = entries
                .Where(entry => LeadsTo(entry.Path, target))
                .Select(entry => (DirectoryListingEntry?)entry)
                .FirstOrDefault();
            if (found is not { } next || !next.IsDirectory || next.IsLink || next.Path.Length <= current.Length)
                return false;
            current = next.Path;
        }

        return true;
    }

    /// <summary>True when <paramref name="path"/> is <paramref name="target"/> or a folder above it.</summary>
    private static bool LeadsTo(string path, string target) =>
        target.StartsWith(path, s_pathComparison)
        && (target.Length == path.Length
            || target[path.Length] == Path.DirectorySeparatorChar
            || target[path.Length] == Path.AltDirectorySeparatorChar);

    /// <summary>Lists one real directory with each entry's directory and link flags.</summary>
    /// <param name="directory">Directory to list.</param>
    /// <returns>The entries of <paramref name="directory"/>.</returns>
    internal static IReadOnlyList<DirectoryListingEntry> ListFileSystem(string directory) =>
        new DirectoryInfo(directory)
            .EnumerateFileSystemInfos("*", s_singleLevel)
            .Select(info => new DirectoryListingEntry(
                info.FullName,
                info is DirectoryInfo,
                (info.Attributes & FileAttributes.ReparsePoint) != 0))
            .ToList();

    private IEnumerable<string> Walk(string root, bool yieldDirectories)
    {
        var pending = new Queue<string>();
        pending.Enqueue(root);
        while (pending.Count > 0)
        {
            foreach (var entry in TryList(pending.Dequeue()))
            {
                if (entry.IsDirectory)
                {
                    if (entry.IsLink)
                        continue;
                    pending.Enqueue(entry.Path);
                    if (yieldDirectories)
                        yield return entry.Path;
                }
                else if (!yieldDirectories)
                {
                    yield return entry.Path;
                }
            }
        }
    }

    private IReadOnlyList<DirectoryListingEntry> TryList(string directory)
    {
        try
        {
            return _list(directory);
        }
        catch (IOException)
        {
            return [];
        }
        catch (UnauthorizedAccessException)
        {
            return [];
        }
    }
}

using Nuke.Common;
using Nuke.Common.ProjectModel;
using Nuke.Common.Tools.DotNet;
using Serilog;
using static Nuke.Common.Tools.DotNet.DotNetTasks;

partial class Build
{
    /// <summary>Run all unit tests, excluding integration test projects and Category=Integration tests.</summary>
    public Target Test => _ => _
        .DependsOn(Compile)
        .Executes(() =>
        {
            // Session-life unit inventory deliberately excludes integration projects.
            // QBrainAi.PluginIntegration.Tests stays on PluginSessionLogIntegration / P6, not Nuke Test.
            var testProjects = Solution.GetAllProjects("*")
                .Where(p => p.Name.EndsWith(".Tests") || p.Name.EndsWith(".Validation"))
                .Where(p => !p.Name.Contains("IntegrationTests"))
                .Where(p => !p.Name.Contains("PluginIntegration"))
                .Where(p => !p.Name.EndsWith(".Validation"))
                .Where(p => !p.Name.Contains("Review.Tests"))
                // Build.Tests references the Nuke _build project and is excluded from the Compile glob,
                // so it has no built assembly to run with --no-build here. Keep Test consistent with Compile.
                .Where(p => !p.Name.EndsWith("Build.Tests"))
                .ToArray();

            var runId = SessionLifeUnitGateReports.NormalizeRunId(TestRunId);
            if (runId is not null)
            {
                SessionLifeUnitGateReports.WriteInventory(
                    RootDirectory,
                    runId,
                    "unit",
                    testProjects.Select(project => (
                        project.Name,
                        SessionLifeUnitGateReports.RelativePath(RootDirectory, project.Path))));
            }

            var failures = new List<string>();
            foreach (var project in testProjects)
            {
                try
                {
                    if (runId is null)
                    {
                        DotNetTest(_ => _
                            .SetProjectFile(project)
                            .SetConfiguration(Configuration)
                            .EnableNoBuild()
                            .SetFilter("Category!=AiReview&Category!=Integration")
                            .SetResultsDirectory(RootDirectory / "TestResults"));
                    }
                    else
                    {
                        var directory = SessionLifeUnitGateReports.LaneProjectDirectory(RootDirectory, runId, "unit", project.Name);
                        Directory.CreateDirectory(directory);
                        // console;verbosity=detailed streams per-test progress into Nuke logs.
                        // PluginIntegration is excluded from unit inventory (PluginSessionLogIntegration/P6).
                        DotNetTest(_ => _
                            .SetProjectFile(project)
                            .SetConfiguration(Configuration)
                            .EnableNoBuild()
                            .SetFilter("Category!=AiReview&Category!=Integration")
                            .SetResultsDirectory(directory)
                            .SetLoggers(
                                $"trx;LogFileName={project.Name}.trx",
                                "console;verbosity=detailed"));
                        SessionLifeUnitGateReports.EnsureCanonicalTrx(directory, $"{project.Name}.trx");
                    }
                }
                catch (Exception ex)
                {
                    if (runId is null)
                        throw;

                    failures.Add(project.Name);
                    Log.Error(ex, "Session-life unit project {Project} failed.", project.Name);
                }
            }

            if (failures.Count > 0)
            {
                throw new InvalidOperationException(
                    "Session-life unit test projects failed: " + string.Join(", ", failures));
            }
        });
}

