function Read-HvTrxRun {
    [CmdletBinding()]
    param([string]$Name, [string]$Root)
    $files = @(Get-ChildItem -LiteralPath $Root -Filter '*.trx' -File -Recurse)
    $projectResults = @()
    $names = [System.Collections.Generic.List[string]]::new()
    foreach ($file in $files) {
        [xml]$document = [System.IO.File]::ReadAllText($file.FullName)
        $counters = $document.TestRun.ResultSummary.Counters
        $results = @($document.TestRun.Results.UnitTestResult)
        $failures = @($results | Where-Object { $_.outcome -ne 'Passed' } | ForEach-Object { [ordered]@{name = $_.testName; outcome = $_.outcome; message = $_.Output.ErrorInfo.Message} })
        $project = Split-Path -Leaf (Split-Path -Parent $file.FullName)
        foreach ($result in $results) { $names.Add($project + '|' + $result.testName) }
        $projectResults += [ordered]@{
            project = $project; path = $file.FullName; sha256 = (Get-FileHash -LiteralPath $file.FullName -Algorithm SHA256).Hash
            total = [int]$counters.total; executed = [int]$counters.executed; passed = [int]$counters.passed; failed = [int]$counters.failed; notExecuted = [int]$counters.notExecuted
            actualResults = $results.Count; failures = $failures; started = $document.TestRun.Times.start; finished = $document.TestRun.Times.finish
            reachabilityRealLink = @($results | Where-Object { $_.testName -like '*FileSystemReach_RealRootAndAncestorLinks_AreNotReachable*' } | ForEach-Object { $_.testName + ':' + $_.outcome })
        }
    }
    $namesByRun[$Name] = $names.ToArray()
    [ordered]@{runId = $Name; root = $Root; projectCount = $files.Count; total = ($projectResults.total | Measure-Object -Sum).Sum; passed = ($projectResults.passed | Measure-Object -Sum).Sum; failed = ($projectResults.failed | Measure-Object -Sum).Sum; notExecuted = ($projectResults.notExecuted | Measure-Object -Sum).Sum; actualResults = ($projectResults.actualResults | Measure-Object -Sum).Sum; projects = $projectResults }
}
foreach ($name in @('ug-r6-reach-mockgate-1','ug-r6-reach-binding-1','ug-r6-precommit-lane-1','ug-r6-linux-test-1','ug-r6-hostile-probe-1','ug-r6-envcoll-mockgate-1','ug-r6-env-binding-1','ug-r6-hostile-wide-1','ug-r6-precommit-lane-2','ug-r6-linux-test-2','ug-r6-hostile-wide-2','ug-r6-hostile-wide-3','ug-r6-linux-lane-1')) {
