<#
.SYNOPSIS
    Read-only: lists every environment variable name that C# sources under the given roots read or set through a
    string literal (Environment.GetEnvironmentVariable / SetEnvironmentVariable / ExpandEnvironmentVariables tokens,
    and nameof-free literal constants passed to them), with the files that use each name and whether the use is a
    read or a write. Used to choose the variables a hostile-environment Test run scripts.
.PARAMETER Roots
    Semicolon-separated directories to scan.
#>
[CmdletBinding()]
param(
    [Parameter(Mandatory)] [string] $Roots
)

Set-StrictMode -Version Latest
$ErrorActionPreference = 'Stop'

Write-Output "Now: $((Get-Date).ToString('s')) roots=$Roots"
$pattern = [regex]'(?<op>GetEnvironmentVariable|SetEnvironmentVariable)\s*\(\s*"(?<name>[A-Za-z_][A-Za-z0-9_]*)"'
$uses = [System.Collections.Generic.Dictionary[string, System.Collections.Generic.SortedSet[string]]]::new()
foreach ($root in @($Roots -split ';' | Where-Object { $_ })) {
    foreach ($file in Get-ChildItem -LiteralPath $root -Recurse -File -Filter '*.cs' | Where-Object { $_.FullName -notmatch '[\\/](bin|obj)[\\/]' }) {
        $text = [System.IO.File]::ReadAllText($file.FullName)
        foreach ($m in $pattern.Matches($text)) {
            $key = $m.Groups['name'].Value
            if (-not $uses.ContainsKey($key)) { $uses[$key] = [System.Collections.Generic.SortedSet[string]]::new() }
            $op = if ($m.Groups['op'].Value -eq 'SetEnvironmentVariable') { 'set' } else { 'get' }
            $relative = [System.IO.Path]::GetRelativePath($root, $file.FullName).Replace('\', '/')
            [void]$uses[$key].Add("$op $([System.IO.Path]::GetFileName($root))/$relative")
        }
    }
}
foreach ($key in ($uses.Keys | Sort-Object)) {
    $entries = @($uses[$key])
    $sets = @($entries | Where-Object { $_ -like 'set *' }).Count
    $gets = @($entries | Where-Object { $_ -like 'get *' }).Count
    Write-Output ('{0} files: get={1} set={2}' -f $key, $gets, $sets)
    foreach ($e in $entries | Select-Object -First 6) { Write-Output "    $e" }
    if ($entries.Count -gt 6) { Write-Output "    ... $($entries.Count - 6) more" }
}
Write-Output "names=$($uses.Count)"

